contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an address `to` and simulate a buyShares call coming from this contract.
    // The test observes balances and totalSupply before and after, and whether the call reverted.
    function run(address to) public payable {
        require(to != address(0), "invalid_to");

        // Read observable before-values
        uint256 beforeRecipient = c.balanceOf(to);
        uint256 beforeTotal = c.totalSupply();

        bool reverted;
        uint256 shares;
        uint256 baseInput;
        uint256 quoteInput;

        try c.buyShares(to) returns (uint256 s, uint256 b, uint256 q) {
            reverted = false;
            shares = s;
            baseInput = b;
            quoteInput = q;
        } catch {
            reverted = true;
            shares = 0;
            baseInput = 0;
            quoteInput = 0;
        }

        // Read observable after-values
        uint256 afterRecipient = c.balanceOf(to);
        uint256 afterTotal = c.totalSupply();

        // General rule:
        // If call reverted then nothing observable changed (recipient balance and totalSupply unchanged).
        // If call did not revert then recipient balance increased by exactly `shares` and totalSupply increased by >= shares.
        // Also require that if non-reverting, shares > 0 implies beforeTotal + shares == afterTotal OR afterTotal >= beforeTotal + shares (to allow for possible initial extra mint of 1001 handled inside contract which increases totalSupply beyond shares minted to `to`).
        assert(
            reverted
                ? (afterRecipient == beforeRecipient && afterTotal == beforeTotal)
                : (afterRecipient == beforeRecipient + shares && afterTotal >= beforeTotal + shares)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test sellShares: provide shareAmount, recipient `to`, mins, optional data length flag, and deadline
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, uint256 dataLen, uint256 deadlineOffset) public payable {
        // keep `to` non-zero to enable callback paths and observable balance checks
        require(to != address(0), "to_nonzero");
        // make a plausible deadline (in future) relative to block.timestamp
        uint256 deadline = block.timestamp + deadlineOffset;

        // Observe before-values: caller is this contract (msg.sender for c calls will be this test contract)
        uint256 beforeCallerShares = c.balanceOf(address(this));
        uint256 beforeToShares = c.balanceOf(to);
        uint256 beforeTotal = c.totalSupply();

        // Observe vault token balances (observable): address(c).balance is Ether held by c, but contract uses ERC20s; we can observe getVaultReserve
        (uint256 beforeBaseReserve, uint256 beforeQuoteReserve) = c.getVaultReserve();
        (uint256 mtBase, uint256 mtQuote) = c.getMtFeeTotal();
        // compute observable transferable balances as in contract: token balances minus mt fees are what sellShares uses to compute baseAmount/quoteAmount
        uint256 observableBaseBalance = beforeBaseReserve; // getVaultReserve returns reserves stored; sellShares computes baseBalance using token.balanceOf - mtFee; after _sync it aligns to reserves; we treat reserves as observable vault holdings for proportional math
        uint256 observableQuoteBalance = beforeQuoteReserve;

        // Build `data` of given length (if any) to possibly trigger callback; keep size moderate
        bytes memory data = new bytes(dataLen);

        bool reverted;
        uint256 outBaseAmount;
        uint256 outQuoteAmount;
        // Call sellShares and catch revert
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) returns (uint256 baseAmount, uint256 quoteAmount) {
            reverted = false;
            outBaseAmount = baseAmount;
            outQuoteAmount = quoteAmount;
        } catch {
            reverted = true;
            outBaseAmount = 0;
            outQuoteAmount = 0;
        }

        // Read after-values
        uint256 afterCallerShares = c.balanceOf(address(this));
        uint256 afterToShares = c.balanceOf(to);
        uint256 afterTotal = c.totalSupply();
        (uint256 afterBaseReserve, uint256 afterQuoteReserve) = c.getVaultReserve();

        // General rule:
        // - If call reverted: no change to caller's shares, no change to recipient shares, and vault reserves unchanged.
        // - If call succeeded: caller's shares decreased by exactly shareAmount, recipient shares unchanged by sellShares (sellShares burns from caller and sends tokens to `to` but does not mint shares to `to`), totalSupply decreased by shareAmount, and the base/quote amounts returned equal the proportional share of the (observable) reserves: base = floor(observableBaseBalance * shareAmount / beforeTotal), quote = floor(observableQuoteBalance * shareAmount / beforeTotal).
        // Note: avoid underflow by using inequalities and identities that hold for uint arithmetic.

        assert(
            reverted
                ? (afterCallerShares == beforeCallerShares && afterToShares == beforeToShares && afterBaseReserve == beforeBaseReserve && afterQuoteReserve == beforeQuoteReserve && afterTotal == beforeTotal)
                : (
                    // shares bookkeeping: caller decreased by shareAmount and totalSupply decreased by shareAmount
                    beforeCallerShares >= shareAmount && afterCallerShares + shareAmount == beforeCallerShares
                    && afterTotal + shareAmount == beforeTotal
                    // recipient shares not increased by sellShares
                    && afterToShares == beforeToShares
                    // reserves reduced by exactly the returned amounts (observed via reserves)
                    && beforeTotal > 0
                    && outBaseAmount == (observableBaseBalance * shareAmount) / beforeTotal
                    && outQuoteAmount == (observableQuoteBalance * shareAmount) / beforeTotal
                    // after reserves equal before minus the amounts transferred out
                    && afterBaseReserve + outBaseAmount == beforeBaseReserve
                    && afterQuoteReserve + outQuoteAmount == beforeQuoteReserve
                )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test transfer: sender is this contract (InvMutTest). We require a reasonable amount to avoid mint/burn limits
    function run(address to, uint256 amount) public payable {
        require(to != address(0), "to_nonzero");
        // Ensure amount is not absurdly large to avoid underflows in observed balances
        require(amount <= 1e30, "amount_too_large");

        // Observe balances before
        uint256 beforeSender = c.balanceOf(address(this));
        uint256 beforeTo = c.balanceOf(to);

        bool reverted;
        // Call transfer; it will revert if balance insufficient
        try c.transfer(to, amount) returns (bool ok) {
            reverted = false;
            // ok should be true per spec, but we won't rely on it
        } catch {
            reverted = true;
        }

        // Observe after balances
        uint256 afterSender = c.balanceOf(address(this));
        uint256 afterTo = c.balanceOf(to);

        // General rule: if transfer reverted, balances unchanged; otherwise sender decreased by amount and recipient increased by amount
        assert(
            reverted
                ? (afterSender == beforeSender && afterTo == beforeTo)
                : (beforeSender >= amount && afterSender + amount == beforeSender && afterTo == beforeTo + amount)
        );
    }

    receive() external payable {}
}
